// unique_ptr: Exclusive Ownership

struct FileHandle { int id; /*...*/ };

// Best Practice Initialization
auto u1 = std::make_unique<FileHandle>(10);

// Exclusive ownership (move semantics)
auto u2 = std::move(u1);

// u1 is now null (u1 == nullptr)

// Access managed object
u2->id = 5;

// Release ownership (dangerous, manual delete needed)
FileHandle* raw_ptr = u2.release();
delete raw_ptr;

// unique_ptr managing an array
auto array_p = std::make_unique<int[]>(20);
array_p[0] = 42;


// shared_ptr: Shared Ownership and Reference Counting

class Widget { /*...*/ };

// Best Practice Initialization
auto s1 = std::make_shared<Widget>(42);

// Shared ownership (copy allowed)
auto s2 = s1;
auto s3 = s1;

// Reference count check
size_t count = s1.use_count(); // count == 3

// Access managed object
s2->method();

// Explicitly relinquish ownership
s3.reset(); // count == 2

// Getting raw pointer
Widget* raw_w = s1.get();


// Custom Deleters (often unique_ptr)

// Resource type and custom cleanup function signature
using Closer = void(*)(FILE*);

// Unique_ptr with custom stateful deleter (lambda)
auto file_p = std::unique_ptr<FILE, Closer>(
    fopen("log.txt", "w"),
    [](FILE* f) { if (f) fclose(f); }
);
// shared_ptr custom deleter
auto buffer = std::shared_ptr<char[]>(
    new char[1024],
    [](char* p) { delete[] p; }
);
